const tomorrow = new Date();
tomorrow.setHours(0,0,0,0);
tomorrow.setDate(tomorrow.getDate() + 1);

return items.filter(item => {
  const raw = item.json.preferred_date;
  if (!raw) return false;

  const parts = raw.toString().split('-');
  if (parts.length !== 3) return false;

  let day = parseInt(parts[0]);
  let month = parseInt(parts[1]) - 1;
  let year = parseInt(parts[2]);
  if (year < 100) year += 2000;

  const bookingDate = new Date(year, month, day);
  bookingDate.setHours(0,0,0,0);

  return bookingDate.getTime() === tomorrow.getTime();
});

const today = new Date();
const weekAgo = new Date();
weekAgo.setDate(weekAgo.getDate() - 7);

const bookings = $('Merge1').all();

const weekBookings = bookings.filter(item => {
  const bookingDate = new Date(item.json.booking_date);
  return bookingDate >= weekAgo && bookingDate <= today;
});

const stats = {
  total_bookings: weekBookings.length,
  website_bookings: weekBookings.filter(b => b.json.source === 'website').length,
  whatsapp_bookings: weekBookings.filter(b => b.json.source === 'whatsapp').length,
  plumbing_bookings: weekBookings.filter(b => b.json.service_type === 'plumbing').length,
  electrical_bookings: weekBookings.filter(b => b.json.service_type === 'electrical').length,
  pending_bookings: weekBookings.filter(b => b.json.status === 'pending').length,
  completed_bookings: weekBookings.filter(b => b.json.status === 'completed').length,
  report_start: weekAgo.toISOString().split('T')[0],
  report_end: today.toISOString().split('T')[0],
  generated_at: today.toISOString()
};

return [{ json: stats }];

